external bool jj_character_valid(int character);

/// The character's body (see JJ_CharacterSettings.innerBody), or 0.
@ffi.Native<ffi.Int64 Function(ffi.Int64)>(isLeaf: true)
external int jj_character_inner_body(int character);

/// Sets the character's velocity, then moves it by one update:
/// CharacterVirtual::ExtendedUpdate, which slides along walls, sticks to the
/// floor (stepDown, pointing down) and climbs stairs (stepUp, pointing up).
/// A zero stepDown or stepUp turns that part off.
@ffi.Native<
  ffi.Void Function(
    ffi.Int64,
    ffi.Float,
    ffi.Pointer<ffi.Float>,
    ffi.Pointer<ffi.Float>,
    ffi.Pointer<ffi.Float>,
    ffi.Pointer<ffi.Float>,
    ffi.Pointer<JJ_CharacterState>,
  )
>()
external void jj_character_step(
  int character,
  double dt,
  ffi.Pointer<ffi.Float> velocity,
  ffi.Pointer<ffi.Float> gravity,
  ffi.Pointer<ffi.Float> stepDown,
  ffi.Pointer<ffi.Float> stepUp,
  ffi.Pointer<JJ_CharacterState> out,
);

/// The character's state without moving it.
@ffi.Native<ffi.Void Function(ffi.Int64, ffi.Pointer<JJ_CharacterState>)>(
  isLeaf: true,
)
external void jj_character_state(
  int character,
  ffi.Pointer<JJ_CharacterState> out,
);

/// Teleports the character; its velocity is kept.
@ffi.Native<ffi.Void Function(ffi.Int64, ffi.Pointer<ffi.Float>)>(isLeaf: true)
external void jj_character_set_position(
  int character,
  ffi.Pointer<ffi.Float> position,
);

/// Writes up to capacity of the character's contacts from its last update;
/// returns how many.
@ffi.Native<
  ffi.Int32 Function(ffi.Int64, ffi.Pointer<JJ_CharacterContact>, ffi.Int32)
>(isLeaf: true)
external int jj_character_contacts(
  int character,
  ffi.Pointer<JJ_CharacterContact> out,
  int capacity,
);

/// Draws the world's bodies (and joints when flags & 1) as lines, writing
/// up to capacity of them, JJ_DEBUG_LINE_FLOATS floats each. Returns how
/// many there are in all (more than capacity: call again with more room),
/// or -1 when the library has no debug renderer.
@ffi.Native<
  ffi.Int32 Function(ffi.Int64, ffi.Uint32, ffi.Pointer<ffi.Float>, ffi.Int32)
>()
external int jj_debug_lines(
  int world,
  int flags,
  ffi.Pointer<ffi.Float> out,
  int capacity,
);

const addresses = _SymbolAddresses();

class _SymbolAddresses {
  const _SymbolAddresses();
  ffi.Pointer<ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void>)>>
  get jj_shape_release => ffi.Native.addressOf(self.jj_shape_release);
  ffi.Pointer<ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void>)>>
  get jj_world_finalize => ffi.Native.addressOf(self.jj_world_finalize);
}

