const int JJ_EVENT_BODY_DEACTIVATED = 7;

const int JJ_QUERY_ALL_HITS = 1;

const int JJ_QUERY_SENSORS = 2;

const int JJ_QUERY_NO_CHARACTERS = 4;

const int JJ_JOINT_FIXED = 0;

const int JJ_JOINT_POINT = 1;

const int JJ_JOINT_HINGE = 2;

const int JJ_JOINT_SLIDER = 3;

const int JJ_JOINT_DISTANCE = 4;

const int JJ_JOINT_SIX_DOF = 5;

const int JJ_MOTOR_OFF = 0;

const int JJ_MOTOR_VELOCITY = 1;

const int JJ_MOTOR_POSITION = 2;

const int JJ_GROUND_ON_GROUND = 0;

